proposal.change:
Title: Distill role-specific review patterns and retrieve them with role-aware, diversified recall
- Diagnosis: the retrieval records show memory stored complete, paper-specific specialist reviews (e.g., quantization, SPN, soft-NLL, PTQ) despite `INSTRUCTION_KNOWLEDGE_ITEM` saying “without paper prose.” This flooded each reviewer’s context with off-topic paper details and taught review style rather than reusable review strategy. Retrieval also embedded only the paper title (or a long SIGN prompt), not the reviewer role plus current paper, so it returned role-matched but topic-mismatched experiences with no coverage control. CoCo feedback shows low Thoro./Complete./Verify. scores tied to recurring missing probes: statistical significance, reproducibility details, baseline comparability, limitation/failure-mode discussion, and impact/compliance statements. The instructions were too vague to force those probes, and the schema lacked fields for subcategory, polarity, pattern, action, evidence style, and calibration, so memory could not be filtered or diversified.
- Memory design changes: extend `KnowledgeItem` with `subcategory`, `polarity`, `pattern`, `action`, `evidence_style`, `calibration`, `source_id`, and `tags`; use the one allowed write LLM call to induce a compact JSON memory record stripped of paper names, numbers, and claims; store only distilled records; keep parsing fallback separate from model/embedding/budget failures.
- Retrieval changes: compose the query from `reviewer_dimension` plus supplied title/abstract; retrieve top-40, filter by role, then diversify across `(subcategory, polarity)` buckets up to 8 entries so each reviewer sees strengths, weaknesses, calibration, reproducibility, comparison, statistics, and impact patterns. Log subcategory/polarity provenance.
- Instruction changes: make the four constants operational: no paper prose in memory; role-aware diversified retrieval; memory is strategy not evidence; every current-paper claim must use Frozen Paper SRC anchors.
- Why this generalizes: distillation separates reusable review patterns from any single paper; role-aware diversified recall gives every dimension balanced, actionable coverage; the schema and instructions are dimension-agnostic across QUAL/CLAR/SIGN/ORIG/POL.

```python
"""Role-local distilled Review Experience with role-aware diversified retrieval."""

import json
import re
from dataclasses import dataclass, field
from hashlib import sha256

INSTRUCTION_KNOWLEDGE_ITEM = (
"Store distilled, role-specific review experience: subcategory, polarity, reusable pattern, "
"action template, evidence-anchor style, and calibration note. Never store paper-specific prose, "
"claims, numbers, or summaries."
)
INSTRUCTION_QUERY = (
"Compose the retrieval query from reviewer_dimension plus the supplied title/abstract; "
"retrieve role-matched experience and diversify across subcategories and polarities."
)
INSTRUCTION_RESPONSE = (
"Use retrieved experience only as review-strategy guidance. Derive every current-paper claim "
"and evidence anchor from the Frozen Paper, not from memory."
)
ALWAYS_ON_KNOWLEDGE = (
"Ground every judgment in the Frozen Paper and cite current-paper SRC anchors; "
"memory supplies reusable review patterns, not evidence."
)


@dataclass
class KnowledgeItem:
topic: str = ""
content: str = ""
reviewer_name: str = ""
reviewer_dimension: str = ""
subcategory: str = ""
polarity: str = ""
pattern: str = ""
action: str = ""
evidence_style: str = ""
calibration: str = ""
source_id: str = ""
tags: list[str] = field(default_factory=list)


@dataclass
class Query:
query_text: str = ""
reviewer_dimension: str = ""


def plan_review(toolkit, query, memory_context):
evidence = toolkit.retrieve_current_s2(limit=5)
selected_ids = []
for item in evidence:
result_id = str(
item.get("paperId") or item.get("paper_id") or item.get("id") or ""
)
if result_id and result_id not in selected_ids:
selected_ids.append(result_id)
return {
"protocol": "evolvable-review-plan-v1",
"s2_disposition": "use" if selected_ids else "consulted_no_use",
"selected_s2_ids": selected_ids,
"decision_label": "seed_always_consult_top5",
"usage_instruction": (
"Use selected frozen S2 evidence only for related-work context; cite its "
"IDs and do not treat it as evidence for claims about the current paper."
),
"context_order": ["memory", "s2", "strategy"],
"review_strategy": (
"Review the Frozen Paper for the assigned specialist dimension. Apply "
"Memory conditionally and keep current-paper claims grounded in the paper."
),
}


class KnowledgeBase:
def __init__(self, toolkit):
self.toolkit = toolkit
self.collection = toolkit.create_vector_collection("research_v3_vector")
self.seen = set()

def _parse_structured(self, text):
if not text:
return None
candidates = [text]
match = re.search(r"\{.*\}", text, flags=re.DOTALL)
if match:
candidates.append(match.group(0))
for candidate in candidates:
try:
data = json.loads(candidate)
except Exception:
continue
if isinstance(data, dict) and (data.get("pattern") or data.get("action")):
return data
return None

def _induce_experience(self, raw_text, item):
role = str(item.reviewer_dimension or item.reviewer_name or "").upper()
prompt = f"""You compile reusable review memory from a complete specialist review.
Return ONLY a JSON object with keys:
"subcategory": short code such as CLAR-WRT, QUAL-MET, SIGN-IMP, ORIG-MTH, POL-IMP.
"polarity": "strength", "weakness", or "neutral".
"pattern": one general review pattern, stripped of paper names, numbers, method names, and claims. Use "the paper", "the method", "the reported result".
"action": one reusable actionable suggestion template.
"evidence_style": how the reviewer should anchor evidence (equation, theorem, table, figure, section, SRC).
"calibration": one sentence on when this pattern should or should not be treated as a weakness.
"tags": list of 3-6 lowercase keywords.
Role: {role}
COMPLETE SPECIALIST REVIEW:
{raw_text}
"""
response = self.toolkit.llm_completion(
[{"role": "user", "content": prompt}]
)
data = self._parse_structured(response)
if data is None:
# Model call succeeded but JSON was malformed. Keep only host-supplied
# distilled fields; never fall back to raw paper prose.
data = {
"subcategory": str(item.subcategory or "").strip(),
"polarity": str(item.polarity or "").strip(),
"pattern": str(item.pattern or "").strip(),
"action": str(item.action or "").strip(),
"evidence_style": str(item.evidence_style or "").strip(),
"calibration": str(item.calibration or "").strip(),
"tags": list(item.tags or []),
}
return data

def _content_from_data(self, data):
tags = data.get("tags") or []
if isinstance(tags, str):
tags = [tags]
tags = [str(t).strip().lower() for t in tags if str(t).strip()]
content = {
"subcategory": str(data.get("subcategory") or "").strip(),
"polarity": str(data.get("polarity") or "").strip(),
"pattern": str(data.get("pattern") or "").strip(),
"action": str(data.get("action") or "").strip(),
"evidence_style": str(data.get("evidence_style") or "").strip(),
"calibration": str(data.get("calibration") or "").strip(),
"tags": tags,
}
return content

def _flatten(self, role, content):
tags = " ".join(content.get("tags") or [])
return " ".join(
str(part)
for part in [
role,
content.get("subcategory", ""),
content.get("polarity", ""),
content.get("pattern", ""),
content.get("action", ""),
content.get("evidence_style", ""),
content.get("calibration", ""),
tags,
]
if part
)

def write(self, item: KnowledgeItem, raw_text: str) -> None:
role = str(item.reviewer_dimension or item.reviewer_name or "").upper()
if not role:
return
structured = str(item.content or "").strip()
data = self._parse_structured(structured)
if data is None:
raw = str(raw_text or "").strip()
if raw:
data = self._induce_experience(raw, item)
else:
# No raw review text; only store if the host already supplied
# a distilled record in the KnowledgeItem fields.
data = {
"subcategory": str(item.subcategory or "").strip(),
"polarity": str(item.polarity or "").strip(),
"pattern": str(item.pattern or "").strip(),
"action": str(item.action or "").strip(),
"evidence_style": str(item.evidence_style or "").strip(),
"calibration": str(item.calibration or "").strip(),
"tags": list(item.tags or []),
}
content = self._content_from_data(data)
if not (content["pattern"] or content["action"]):
return
flat = self._flatten(role, content)
item_id = sha256(
(
f"{role}\n{content['subcategory']}\n{content['polarity']}\n"
f"{content['pattern']}\n{content['action']}"
).encode("utf-8")
).hexdigest()
if item_id in self.seen:
return
self.seen.add(item_id)
metadata = {
"role": role,
"topic": str(item.topic or ""),
"subcategory": content["subcategory"],
"polarity": content["polarity"],
"tags": ",".join(content["tags"]),
"source_id": str(item.source_id or ""),
}
self.collection.add(
[json.dumps(content, ensure_ascii=False)],
self.toolkit.embed([flat]),
[metadata],
[item_id],
)

def _format_entry(self, result):
metadata = result.get("metadata") or {}
try:
content = json.loads(result.get("text") or "{}")
except Exception:
content = {}
identifier = result.get("id") or ""
parts = [
f"[REVIEW EXPERIENCE {identifier} | "
f"{metadata.get('role', '')} | "
f"{content.get('subcategory') or metadata.get('subcategory', '')} | "
f"{content.get('polarity') or metadata.get('polarity', '')}]"
]
pattern = content.get("pattern") or ""
action = content.get("action") or ""
evidence_style = content.get("evidence_style") or ""
calibration = content.get("calibration") or ""
tags = content.get("tags") or []
if pattern:
parts.append(f"Pattern: {pattern}")
if action:
parts.append(f"Action: {action}")
if evidence_style:
parts.append(f"Evidence style: {evidence_style}")
if calibration:
parts.append(f"Calibration: {calibration}")
if tags:
parts.append("Tags: " + ", ".join(str(t) for t in tags))
return "\n".join(parts)

def _diversify(self, results, max_entries=8):
selected = []
counts = {}
for result in results:
metadata = result.get("metadata") or {}
key = (
str(metadata.get("subcategory") or "unknown"),
str(metadata.get("polarity") or "unknown"),
)
if counts.get(key, 0) >= 2:
continue
selected.append(result)
counts[key] = counts.get(key, 0) + 1
if len(selected) >= max_entries:
break
if len(selected) < max_entries:
chosen_ids = {item.get("id") for item in selected}
for result in results:
if result.get("id") in chosen_ids:
continue
selected.append(result)
if len(selected) >= max_entries:
break
return selected

def read(self, query: Query) -> str:
role = str(query.reviewer_dimension or "").upper()
if not query.query_text and not role:
return ""
query_text = "\n".join(
part for part in [role, query.query_text] if part
)
embedding = self.toolkit.embed([query_text])[0]
results = self.collection.query(embedding, top_k=40)
role_results = [
result
for result in results
if str((result.get("metadata") or {}).get("role") or "") == role
]
if not role_results:
return ""
selected = self._diversify(role_results, max_entries=8)
self.toolkit.log(
"retrieval_hits",
[
{
"id": item.get("id"),
"score": item.get("score"),
"role": role,
"subcategory": (item.get("metadata") or {}).get("subcategory"),
"polarity": (item.get("metadata") or {}).get("polarity"),
}
for item in selected
],
)
entries = [self._format_entry(item) for item in selected]
return "\n\n".join(self.toolkit.select_memory_entries(entries))
